BEGIN;
SET LOCAL lock_timeout='5s'; SET LOCAL statement_timeout='60s';
LOCK TABLE public.questions IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE swsi_before ON COMMIT DROP AS SELECT id, to_jsonb(q) AS row FROM public.questions q;
CREATE TEMP TABLE swsi_batch(id text primary key, status text, note text, url text) ON COMMIT DROP;
INSERT INTO swsi_batch VALUES ('SP-115-2-039','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2026-07-25。本題考兒童及少年未來教育與發展帳戶條例第18條：開戶人申請退出兒少教育發展帳戶，直轄市、縣（市）主管機關應自其申請日起一年內派員輔導，期滿仍決定退出者僅得請領自存款及其利息。本條例於 2018-06-06 制定公布施行，其後未曾修正，考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050205'),('SP106-2-12','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2017-07-29。本題考兒童及少年未來教育與發展帳戶條例之前身，即 2016 年 11 月行政院核定之「兒童與少年未來教育及發展帳戶」方案，考試時本條例尚未制定；2018-06-06 制定公布之本條例將方案法制化（第26條規定已參與方案者視同本條例之開戶人），其後未曾修正。現行條文：第6條適用對象包括依法安置二年以上之兒童及少年，選項(A)仍錯誤；第18條規定申請退出者經一年輔導後僅得請領自存款及其利息，並非保留三年緩衝期，選項(C)仍錯誤；第16條規定自存款未達開戶金者仍得提領自存款及其利息，選項(D)仍錯誤；惟第17條雖規定未滿十八歲開戶人因死亡、罹患嚴重疾病或為嚴重身心障礙得申請提領儲金並結清帳戶，第18條另有申請退出後結清之途徑，且第19條規定結清後未滿三年不得重行申請開立，並非結清後即永久不得重新開立，選項(B)已不符現行條文，依現行條文本題已無正確選項。本題官方答案依考試時之方案規定判定；作答時請以現行條文為準。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050205'),('SP106-2-17','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2017-07-29。本題考兒童及少年未來教育與發展帳戶條例之前身，即 2016 年 11 月行政院核定之「兒童與少年未來教育及發展帳戶」方案，考試時本條例尚未制定；2018-06-06 制定公布之本條例將方案法制化（第26條規定已參與方案者視同本條例之開戶人），其後未曾修正。現行條文：第14條規定帳戶利息免納綜合所得稅，選項(B)「孳息不得列入免納綜合所得稅」仍錯誤；第21條規定儲金不計入家庭總收入或家庭財產、第20條規定喪失資格後一年內仍撥付政府相對提撥款且得保存帳戶持續存款、第16條規定儲金用途以就學、就業、職業訓練或創業為限，選項(A)(C)(D)仍與條文相符。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050205'),('SP110-1-40','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2021-02-06。本題考兒童及少年未來教育與發展帳戶條例第3條：開戶人指完成開立兒少教育發展帳戶之兒童或少年。本條例於 2018-06-06 制定公布施行，其後未曾修正，考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050205'),('SP112-1-33','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2023-02-18。本題考兒童及少年未來教育與發展帳戶條例第1條立法目的：建立兒少教育發展帳戶制度，協助資產累積、教育投資及就業創業，不含健康照護。本條例於 2018-06-06 制定公布施行，其後未曾修正，考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050205'),('SP112-1-34','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2023-02-18。本題考兒童及少年未來教育與發展帳戶條例之理論基礎；第1條明定本條例係協助兒童及少年資產累積、教育投資及就業創業，與資產累積理論相符。本條例於 2018-06-06 制定公布施行，其後未曾修正，考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050205'),('SP115-1-40','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2026-02-07。本題考兒童及少年未來教育與發展帳戶條例第14條：帳戶利息於滿十八歲前依一年期定期儲蓄存款一般牌告機動利率計算並免納綜合所得稅；自滿十八歲之日起至結清提領之日止之利息，依承辦機構牌告活期儲蓄存款機動利率計算，並應繳納綜合所得稅。本條例於 2018-06-06 制定公布施行，其後未曾修正，考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050205');
DO $g$ BEGIN
IF (SELECT count(*) FROM swsi_before)<>4800 THEN RAISE EXCEPTION 'count'; END IF;
IF (SELECT count(*) FROM swsi_batch)<>7 THEN RAISE EXCEPTION 'batch size'; END IF;
IF (SELECT count(*) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_status='unreviewed' AND q.legal_checked_at IS NULL AND q.legal_note IS NULL AND q.legal_source_url IS NULL)<>7 THEN RAISE EXCEPTION 'preimage mismatch'; END IF;
END $g$;
UPDATE public.questions q SET legal_status=b.status, legal_checked_at='2026-11-25T12:00:00+00:00'::timestamptz, legal_note=b.note, legal_source_url=b.url
FROM swsi_batch b WHERE q.id=b.id;
DO $a$ BEGIN
IF (SELECT md5(string_agg(concat_ws(chr(31),q.id,q.legal_status,q.legal_note,q.legal_source_url),chr(30) ORDER BY q.id)) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_checked_at='2026-11-25T12:00:00+00:00'::timestamptz)<>'f2cac299fd01244fb504b23c45608296' THEN RAISE EXCEPTION 'postimage mismatch'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b FULL JOIN public.questions q USING(id) WHERE coalesce(b.id,q.id) NOT IN (SELECT id FROM swsi_batch) AND b.row IS DISTINCT FROM to_jsonb(q)) THEN RAISE EXCEPTION 'unrelated change'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b JOIN public.questions q USING(id) WHERE b.id IN (SELECT id FROM swsi_batch) AND (b.row - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url') IS DISTINCT FROM (to_jsonb(q) - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url')) THEN RAISE EXCEPTION 'non-legal field changed'; END IF;
END $a$;
SELECT count(*) FILTER (WHERE q.legal_status='verified_current') verified_6, count(*) FILTER (WHERE q.legal_status='changed') changed_1, count(*) total_7 FROM public.questions q JOIN swsi_batch b USING(id);
COMMIT;
